-- 07_LOOKUP_SYNC.sql (v2 로직) — PK 6컬럼(SEG1~5) MERGE + SEG5 변형 구행 선삭제 + VERIFY

DELETE FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
 WHERE LOOKUP_TYPE = 'GET_ADMIN_GROUP' AND NVL(SEGMENT1,'~') = NVL('ADMIN','~') AND NVL(SEGMENT2,'~') = NVL('ALL','~') AND NVL(SEGMENT3,'~') = NVL('-','~') AND NVL(SEGMENT4,'~') = NVL('-','~')
   AND NVL(SEGMENT5,'~') <> NVL('-','~');
MERGE INTO SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL T
USING (SELECT 'GET_ADMIN_GROUP' AS LOOKUP_TYPE, 'ADMIN' AS SEGMENT1, 'ALL' AS SEGMENT2, '-' AS SEGMENT3, '-' AS SEGMENT4, '-' AS SEGMENT5 FROM DUAL) S ON (NVL(T.LOOKUP_TYPE,'~') = NVL(S.LOOKUP_TYPE,'~') AND NVL(T.SEGMENT1,'~') = NVL(S.SEGMENT1,'~') AND NVL(T.SEGMENT2,'~') = NVL(S.SEGMENT2,'~') AND NVL(T.SEGMENT3,'~') = NVL(S.SEGMENT3,'~') AND NVL(T.SEGMENT4,'~') = NVL(S.SEGMENT4,'~') AND NVL(T.SEGMENT5,'~') = NVL(S.SEGMENT5,'~'))
WHEN MATCHED THEN UPDATE SET ATTRIBUTE1 = 'Y', ATTRIBUTE2 = ' ', ATTRIBUTE3 = ' ', ATTRIBUTE4 = ' ', DISPLAY_SEQ = '1', VALID_YN = 'Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, DISPLAY_SEQ, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('GET_ADMIN_GROUP', 'ADMIN', 'ALL', '-', '-', '-', 'Y', ' ', ' ', ' ', '1', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
