-- VERIFY: (SEG1~4) 논리키 중복 0 기대
SELECT SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, COUNT(*) FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
 WHERE LOOKUP_TYPE IN ('GET_ADMIN_GROUP_MEASURE','GET_ADMIN_GROUP') AND SEGMENT2 IN ('DMF0042','ALL')
 GROUP BY SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4 HAVING COUNT(*) > 1;
